correct_code:
class CircuitBreaker {
  constructor(threshold = 3, resetTimeout = 30000) {
    this.failures = 0;
    this.threshold = threshold;
    this.resetTimeout = resetTimeout;
    this.state = 'CLOSED';
    this.openedAt = null;
  }
  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.openedAt > this.resetTimeout) {
        this.state = 'HALF-OPEN';
      } else {
        throw new Error('circuit open');
      }
    }
    try {
      const result = await fn();
      if (this.state === 'HALF-OPEN') {
        this.state = 'CLOSED';
        this.failures = 0;
      }
      return result;
    } catch (err) {
      this.failures++;
      if (this.failures >= this.threshold) {
        this.state = 'OPEN';
        this.openedAt = Date.now();
      }
      throw err;
    }
  }
}

solution.code:
class CircuitBreaker {
  constructor(threshold = 3, resetTimeout = 30000) {
    this.failures = 0;
    this.threshold = threshold;
    this.resetTimeout = resetTimeout;
    this.state = 'CLOSED';
    this.openedAt = null;
  }
  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.openedAt > this.resetTimeout) {
        this.state = 'HALF-OPEN';
      } else {
        throw new Error('circuit open');
      }
    }
    try {
      const result = await fn();
      if (this.state === 'HALF-OPEN') {
        this.state = 'CLOSED';
        this.failures = 0;
      }
      return result;
    } catch (err) {
      this.failures++;
      if (this.failures >= this.threshold) {
        this.state = 'OPEN';
        this.openedAt = Date.now();
      }
      throw err;
    }
  }
}

