def groupAnagrams(strs):
    from collections import defaultdict
    d=defaultdict(list)
    for s in strs: d[''.join(sorted(s))].append(s)
    return list(d.values())

def longestKDistinct(s, k):
    from collections import defaultdict
    count = defaultdict(int)
    l = best = 0
    for r, ch in enumerate(s):
        count[ch] += 1
        while len(count) > k:
            count[s[l]] -= 1
            if count[s[l]] == 0:
                del count[s[l]]
            l += 1
        best = max(best, r - l + 1)
    return best

def levelOrder(root):
    if not root:
        return []
    from collections import deque
    q = deque([root])
    ans = []
    while q:
        level = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        ans.append(level)
    return ans

