from ast import literal_eval
nums = literal_eval(input())
target = int(input())
def bound(go_left):
    lo, hi, res = 0, len(nums) - 1, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            res = mid
            if go_left:
                hi = mid - 1
            else:
                lo = mid + 1
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return res
print('[' + str(bound(True)) + ',' + str(bound(False)) + ']')

