def trap_rain_water(heights):
    lo, hi = 0, len(heights) - 1
    lmax = rmax = 0
    water = 0
    while lo <= hi:
        if lmax <= rmax:
            if heights[lo] >= lmax:
                lmax = heights[lo]
            else:
                water += lmax - heights[lo]
            lo += 1
        else:
