    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1:
            return i
    return -1

def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    arr = list(s)
    i, j = 0, len(arr) - 1
    while i < j:
        while i < j and arr[i] not in vowels:
            i += 1
        while i < j and arr[j] not in vowels:
            j -= 1
        arr[i], arr[j] = arr[j], arr[i]
        i += 1
        j -= 1
    return "".join(arr)

def run_length_compress(s):
    if not s:
        return ""
    out = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            out.append(s[i - 1] + str(count))
            count = 1
    out.append(s[-1] + str(count))
    return "".join(out)

def count_and_say(n):
    s = "1"
    for _ in range(n - 1):
        out = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            out.append(str(j - i) + s[i])
            i = j
        s = "".join(out)
    return s

def max_sum_fixed_k(nums, k):
    if k <= 0 or k > len(nums):
        return None
    cur = sum(nums[:k])
    best = cur
    for i in range(k, len(nums)):
        cur += nums[i] - nums[i - k]
        best = max(best, cur)
    return best

def min_swaps_group_ones(nums):
    ones = nums.count(1)
    if ones <= 1:
        return 0
    cur = sum(nums[:ones])
    best = cur
    for i in range(ones, len(nums)):
        cur += nums[i] - nums[i - ones]
        best = max(best, cur)
    return ones - best

def shortest_substr_all_distinct(s):
    from collections import defaultdict
    need = set(s)
    if not need:
        return 0
    want = len(need)
    seen = defaultdict(int)
    have, left, best = 0, 0, len(s) + 1
    for right, ch in enumerate(s):
        seen[ch] += 1
        if seen[ch] == 1:
            have += 1
        while have == want:
            best = min(best, right - left + 1)
            lc = s[left]
            seen[lc] -= 1
            if seen[lc] == 0:
                have -= 1
            left += 1
    return best

